latest.script:
function parseList(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.wmh1234.com').replace(/\/$/, '');
  if (typeof html !== 'string') return [];
  // 只取“推荐漫画”区之前的内容，避免把推荐卡片混入结果
  var cut = html.indexOf('推荐漫画');
  if (cut > 0) html = html.substring(0, cut);
  var results = [];
  var seen = {};
  var aRe = /<a\s+([^>]*)>/gi;
  var m;
  while ((m = aRe.exec(html)) !== null) {
    var attrs = m[1];
    if (!/class="[^"]*comic-card__link/.test(attrs)) continue;
    var hrefM = attrs.match(/href="([^"]+)"/);
    if (!hrefM) continue;
    var href = hrefM[1];
    if (href.indexOf('/comic/') !== 0) continue;
    if (seen[href]) continue;
    var start = m.index + m[0].length;
    var end = html.indexOf('</a>', start);
    if (end < 0) continue;
    var block = html.substring(start, end);
    var title = '';
    var tMatch = block.match(/class="comic-card__title"[^>]*>([\s\S]*?)<\/h[0-9]>/i) || block.match(/<img[^>]+alt="([^"]+)"/i);
    if (tMatch) title = tMatch[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    if (!title) continue;
    var cover = '';
    var dsMatch = block.match(/<img[^>]+data-src="([^"]+)"[^>]*>/i);
    if (dsMatch) cover = dsMatch[1];
    else { var sMatch = block.match(/<img[^>]+src="([^"]+)"[^>]*>/i); if (sMatch) cover = sMatch[1]; }
    if (cover && cover.indexOf('placeholder') >= 0) cover = '';
    if (cover && cover.indexOf('/') === 0) cover = baseUrl + cover;
    seen[href] = 1;
    results.push({ id: href, title: title, cover: cover, detailUrl: baseUrl + href });
  }
  return results;
}

