detail.script:
function parseDetail(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.wmh1234.com').replace(/\/$/, '');
  if (typeof html !== 'string') html = '';
  var stripTags = function(s) { return s.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim(); };
  var title = '';
  var titleMatch = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  if (titleMatch) title = stripTags(titleMatch[1]);
  if (!title) {
    var titleMetaMatch = html.match(/<meta[^>]*property="og:title"[^>]*content="([^"]+)"/i);
    if (titleMetaMatch) title = titleMetaMatch[1];
  }
  if (!title) {
    var titleDivMatch = html.match(/<div[^>]*class="[^"]*comic-title[^"]*"[^>]*>([\s\S]*?)<\/div>/i) || html.match(/<p[^>]*class="[^"]*name[^"]*"[^>]*>([\s\S]*?)<\/p>/i);
    if (titleDivMatch) title = stripTags(titleDivMatch[1]);
  }
  var cover = '';
  var coverMetaMatch = html.match(/<meta[^>]*property="og:image"[^>]*content="([^"]+)"/i);
  if (coverMetaMatch) cover = coverMetaMatch[1];
  if (!cover) {
    var coverImgMatch = html.match(/<img[^>]*class="[^"]*cover[^"]*"[^>]+src="([^"]+)"/i) || html.match(/<div[^>]*class="[^"]*detail-cover[^"]*"[^>]*>\s*<img[^>]+src="([^"]+)"/i);
    if (coverImgMatch) cover = coverImgMatch[1];
  }
  if (!cover) {
    var lazyCoverMatch = html.match(/<img[^>]+class="[^"]*lazy[^"]*"[^>]+data-original="([^"]+)"/i);
    if (lazyCoverMatch) cover = lazyCoverMatch[1];
  }
  if (cover && cover.startsWith('/')) cover = baseUrl + cover;
  var description = '';
  var descMatch = html.match(/<meta[^>]*name="description"[^>]*content="([^"]*)"/i) || html.match(/<meta[^>]*property="og:description"[^>]*content="([^"]*)"/i);
  if (descMatch) description = descMatch[1].trim();
  if (!description) {
    var descDiv = html.match(/<div[^>]*class="[^"]*intro[^"]*"[^>]*>([\s\S]*?)<\/div>/i) || html.match(/<p[^>]*class="[^"]*desc[^"]*"[^>]*>([\s\S]*?)<\/p>/i);
    if (descDiv) description = stripTags(descDiv[1]);
  }
  var author = '';
  var authorMatch = html.match(/作者[：:]\s*([^<\n]+)/i) || html.match(/<span[^>]*class="[^"]*author[^"]*"[^>]*>([\s\S]*?)<\/span>/i);
  if (authorMatch) author = stripTags(authorMatch[1]);
  if (!author) {
    var authorLinkMatch = html.match(/<a[^>]*href="[^"]*author[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
    if (authorLinkMatch) author = stripTags(authorLinkMatch[1]);
  }
  var status = '';
  var statusMatch = html.match(/状态[：:]\s*([^<\n]+)/i) || html.match(/更新[：:]\s*([^<\n]+)/i) || html.match(/(连载中|已完结|完结)/i);
  if (statusMatch) status = statusMatch[1] || statusMatch[0];
  var tags = [];
  var tagUrls = [];
  var tagRe = /<a[^>]+href="([^"]*\/(?:tag|genre|category|type)\/[^"]+)"[^>]*>([\s\S]*?)<\/a>/gi;
  var tm;
  while ((tm = tagRe.exec(html)) !== null) {
    var tHref = tm[1];
    if (tHref.indexOf('/') === 0) tHref = baseUrl + tHref;
    var t = stripTags(tm[2]);
    if (t && tags.indexOf(t) === -1) { tags.push(t); tagUrls.push(tHref); }
  }
  var comicId = '';
  var comicIdMatch = html.match(/data-comic-id="(\d+)"/i) || html.match(/data-id="(\d+)"/i) || html.match(/comic_id=(\d+)/i);
  if (comicIdMatch) comicId = comicIdMatch[1];
  var detailUrl = ctx.url || (baseUrl + (ctx.id || ''));
  return {
    id: ctx.id || '',
    title: title,
    cover: cover,
    coverUrl: cover,
    author: author,
    description: description,
    status: status,
    tags: tags,
    tagUrls: tagUrls,
    comicId: comicId,
    detailUrl: detailUrl
  };
}

chapters.script:
function parseChapters(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.wmh1234.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string' || html.length < 50) return [];
  var results = [];
  var seen = {};
  var chapterRe = /<a\s+([^>]*)href="([^"]+)"([^>]*)>([\s\S]*?)<\/a>/gi;
  var match;
  while ((match = chapterRe.exec(html)) !== null) {
    var href = match[2];
    var block = match[4];
    if (href.indexOf('/chapter/') < 0 && href.indexOf('/read/') < 0 && href.indexOf('/comic/') < 0) continue;
    if (seen[href]) continue;
    var title = '';
    var titleMatch = block.match(/<span[^>]*>([\s\S]*?)<\/span>/i);
    if (titleMatch) title = titleMatch[1].replace(/<[^>]+>/g, '').trim();
    if (!title) {
      title = block.replace(/<[^>]+>/g, '').trim();
    }
    if (!title) continue;
    seen[href] = 1;
    var updatedAt = '';
    var timeMatch = html.match(new RegExp(href.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[\\s\\S]*?(\\d{4}[-/]\\d{1,2}[-/]\\d{1,2})', 'i'));
    if (timeMatch) updatedAt = timeMatch[1];
    var fullUrl = href.indexOf('http') === 0 ? href : baseUrl + href;
    results.push({
      id: href,
      title: title,
      url: fullUrl,
      updatedAt: updatedAt
    });
  }
  return results;
}

images.script:
function parseImages(html, context) {
  var ctx = context || {};
  var baseUrl = (ctx.baseUrl || 'https://m.wmh1234.com').replace(/\/$/, '');
  if (!html || typeof html !== 'string') html = '';
  var results = [];
  var imgRe = /<img[^>]+src="([^"]+)"[^>]*>/gi;
  var match;
  while ((match = imgRe.exec(html)) !== null) {
    var src = match[1];
    if (!src) continue;
    if (src.indexOf('data:') === 0) continue;
    if (src.match(/(logo|icon|avatar|banner|qrcode|loading|spinner|advertisement)/i)) continue;
    if (src.startsWith('/')) src = baseUrl + src;
    if (results.indexOf(src) === -1) results.push(src);
  }
  if (results.length === 0) {
    var dataSrcRe = /<img[^>]+data-src="([^"]+)"[^>]*>/gi;
    while ((match = dataSrcRe.exec(html)) !== null) {
      var src2 = match[1];
      if (!src2) continue;
      if (src2.indexOf('data:') === 0) continue;
      if (src2.match(/(logo|icon|avatar|banner|qrcode|loading|spinner|advertisement)/i)) continue;
      if (src2.startsWith('/')) src2 = baseUrl + src2;
      if (results.indexOf(src2) === -1) results.push(src2);
    }
  }
  if (results.length === 0) {
    var dataOriginalRe = /<img[^>]+data-original="([^"]+)"[^>]*>/gi;
    while ((match = dataOriginalRe.exec(html)) !== null) {
      var src3 = match[1];
      if (!src3) continue;
      if (src3.indexOf('data:') === 0) continue;
      if (src3.match(/(logo|icon|avatar|banner|qrcode|loading|spinner|advertisement)/i)) continue;
      if (src3.startsWith('/')) src3 = baseUrl + src3;
      if (results.indexOf(src3) === -1) results.push(src3);
    }
  }
  return results;
}

